    if (srcFixed <= dstLen) {
        scaleScalable = scale;
        scaleFixed = 1.0f;
    } else {
        scaleScalable = 0.0f;
        scaleFixed = scale;
    }

    // Precompute dstDelta values (no loop-carried dependency in this separated loop)
